const PW_DUE=100,PW_CLOSE=80;function pwNum(v){const n=parseFloat(v);return isFinite(n)?n:0}function pwIsLocked(player){const until=player&&player.priceLockedUntil;if(!until)return!1;const t=Date.parse(until);return isFinite(t)&&t>Date.now()}const PW_TICKER_FLOOR=20;function pwClassify(player,floor){if(!player||pwIsLocked(player))return null;const progress=pwNum(player.priceProgress);if(!progress)return null;const proj=player.priceProjection||[],projected=proj.length>1?pwNum(proj[1]):progress,mag=Math.abs(progress);return mag<(floor===void 0?80:floor)?null:{id:player.id,player,dir:progress>0?"rise":"fall",tier:mag>=100?"due":"close",progress,projected}}function pwMovers(players,limit,floor){const out={risers:[],fallers:[]};(players||[]).forEach(p=>{const c=pwClassify(p,floor);c&&(c.dir==="rise"?out.risers:out.fallers).push(c)});const byProgress=(a,b)=>Math.abs(b.progress)-Math.abs(a.progress);return out.risers.sort(byProgress),out.fallers.sort(byProgress),limit&&(out.risers=out.risers.slice(0,limit),out.fallers=out.fallers.slice(0,limit)),out}function pwLabel(c){return c.tier==="due"?c.dir==="rise"?"Rise due":"Drop due":Math.round(Math.abs(c.progress))+"% there"}function pwDetail(c){const dir=c.dir==="rise"?"rise":"drop";if(c.tier==="due")return`The meter is full, so this ${dir} happens at the next daily price update.`;const proj=Math.round(Math.abs(c.projected));return Math.abs(c.projected)>=100?`${Math.round(Math.abs(c.progress))}% of the way. The game projects ${proj}% by tomorrow, which would cross the line \u2014 though most players this close do not move tonight.`:`${Math.round(Math.abs(c.progress))}% of the way, and not projected to cross yet.`}function pwPriceHistory(player,history){if(!player)return null;const nowTenths=Math.round(pwNum(player.price)*10);if(!nowTenths)return null;const startTenths=nowTenths-pwNum(player.costChangeStart),points=[];(history||[]).forEach(row=>{const v=pwNum(row&&row.value),gw=row&&row.round;!v||gw==null||points.push({gw:Number(gw),tenths:v})}),points.sort((a,b)=>a.gw-b.gw);const last=points[points.length-1];!last||last.tenths!==nowTenths?points.push({gw:null,tenths:nowTenths,isNow:!0}):last.isNow=!0;const moves=[];let prev=points.length?points[0].tenths:startTenths;points.length&&points[0].tenths!==startTenths&&(moves.push({gw:points[0].gw,from:startTenths,to:points[0].tenths}),prev=points[0].tenths),points.slice(1).forEach(pt=>{pt.tenths!==prev&&moves.push({gw:pt.gw,from:prev,to:pt.tenths,isNow:!!pt.isNow}),prev=pt.tenths});const all=points.map(p=>p.tenths).concat([startTenths]);return{startTenths,nowTenths,netTenths:nowTenths-startTenths,start:startTenths/10,now:nowTenths/10,net:(nowTenths-startTenths)/10,high:Math.max.apply(null,all)/10,low:Math.min.apply(null,all)/10,rises:moves.filter(m=>m.to>m.from).length,falls:moves.filter(m=>m.to<m.from).length,moves,points:points.length>1?points:[{gw:null,isStart:!0,tenths:startTenths}].concat(points)}}function pwEngineReady(){return typeof pwClassify=="function"}
